-- ============================================================================
-- 测试数据导入（朱琳 / 第二批）→ 租户 2012 固邦防腐材料制造有限公司
-- 数据来源：C:\Users\B\Desktop\测试数据_朱琳（16 个 CSV）
-- 日期：2026-09-18
--
-- 说明：
--   1. 该批数据与 2012 现有数据严格衔接：现有 产品1001+/客户3001+/商机5001+/合同6001+/回款计划7001+，
--      本批为 产品1101+/线索2101+/客户3101+/联系人4101+/商机5101+/合同6101+/回款计划7101+/回款8101+/跟进9101+；
--   2. 组织与主数据（部门 1-7、用户 101-111、产品分类 10/11/12/13/20/30/40）此前已导入，本批不再重复，
--      仅做 ID 映射：用户 101..111 → 2012 实际用户 ID；产品分类沿用同 ID；
--   3. 商机按新方案写入 stage/business_state/win_rate（CSV 的文本阶段映射到固定阶段 1..5）；
--   4. 本脚本幂等，可重复执行（先按号段清理再插入）。
--
-- 执行方式：
--   docker cp sql/2026-09-18-import-testdata-zhulin-tenant-2012.sql <mysql容器>:/tmp/
--   docker exec <mysql容器> sh -c "mysql --default-character-set=utf8mb4 -uroot -p'xxx' ruoyi-vue-pro < /tmp/2026-09-18-import-testdata-zhulin-tenant-2012.sql"
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 0. 幂等清理（仅清理本批号段）
-- ---------------------------------------------------------------------------
DELETE FROM `crm_permission` WHERE tenant_id = 2012 AND (
    (biz_type = 2 AND biz_id BETWEEN 3101 AND 3199)
 OR (biz_type = 4 AND biz_id BETWEEN 5101 AND 5199)
 OR (biz_type = 5 AND biz_id BETWEEN 6101 AND 6199));
DELETE FROM `crm_follow_up_record` WHERE tenant_id = 2012 AND id BETWEEN 9101 AND 9199;
DELETE FROM `crm_receivable`      WHERE tenant_id = 2012 AND id BETWEEN 8101 AND 8199;
DELETE FROM `crm_receivable_plan` WHERE tenant_id = 2012 AND id BETWEEN 7101 AND 7199;
DELETE FROM `crm_contract_product` WHERE tenant_id = 2012 AND contract_id BETWEEN 6101 AND 6199;
DELETE FROM `crm_contract`        WHERE tenant_id = 2012 AND id BETWEEN 6101 AND 6199;
DELETE FROM `crm_business_product` WHERE tenant_id = 2012 AND business_id BETWEEN 5101 AND 5199;
DELETE FROM `crm_business`        WHERE tenant_id = 2012 AND id BETWEEN 5101 AND 5199;
DELETE FROM `crm_contact`         WHERE tenant_id = 2012 AND id BETWEEN 4101 AND 4199;
DELETE FROM `crm_customer`        WHERE tenant_id = 2012 AND id BETWEEN 3101 AND 3199;
DELETE FROM `crm_clue`            WHERE tenant_id = 2012 AND id BETWEEN 2101 AND 2199;
DELETE FROM `crm_product`         WHERE tenant_id = 2012 AND id BETWEEN 1101 AND 1199;

