-- 已赢单商机补齐签约信息与关闭信息
UPDATE `crm_business` SET closed_at = update_time, closed_by = 80446, sign_date = deal_time, sign_amount = total_price
WHERE tenant_id = 2012 AND id IN (5102, 5105);

