-- 13. 导入结果自查
-- ---------------------------------------------------------------------------
SELECT '=== 本批导入结果(租户2012) ===' AS info;
SELECT 'product 1101+' AS k, COUNT(*) AS c FROM crm_product WHERE tenant_id = 2012 AND id BETWEEN 1101 AND 1199
UNION ALL SELECT 'clue 2101+', COUNT(*) FROM crm_clue WHERE tenant_id = 2012 AND id BETWEEN 2101 AND 2199
UNION ALL SELECT 'customer 3101+', COUNT(*) FROM crm_customer WHERE tenant_id = 2012 AND id BETWEEN 3101 AND 3199
UNION ALL SELECT 'contact 4101+', COUNT(*) FROM crm_contact WHERE tenant_id = 2012 AND id BETWEEN 4101 AND 4199
UNION ALL SELECT 'business 5101+', COUNT(*) FROM crm_business WHERE tenant_id = 2012 AND id BETWEEN 5101 AND 5199
UNION ALL SELECT 'business_product(5101+)', COUNT(*) FROM crm_business_product WHERE tenant_id = 2012 AND business_id BETWEEN 5101 AND 5199
UNION ALL SELECT 'contract 6101+', COUNT(*) FROM crm_contract WHERE tenant_id = 2012 AND id BETWEEN 6101 AND 6199
UNION ALL SELECT 'contract_product(6101+)', COUNT(*) FROM crm_contract_product WHERE tenant_id = 2012 AND contract_id BETWEEN 6101 AND 6199
UNION ALL SELECT 'receivable_plan 7101+', COUNT(*) FROM crm_receivable_plan WHERE tenant_id = 2012 AND id BETWEEN 7101 AND 7199
UNION ALL SELECT 'receivable 8101+', COUNT(*) FROM crm_receivable WHERE tenant_id = 2012 AND id BETWEEN 8101 AND 8199
UNION ALL SELECT 'follow_up 9101+', COUNT(*) FROM crm_follow_up_record WHERE tenant_id = 2012 AND id BETWEEN 9101 AND 9199
UNION ALL SELECT 'permission(本批)', COUNT(*) FROM crm_permission WHERE tenant_id = 2012 AND ((biz_type = 2 AND biz_id BETWEEN 3101 AND 3199) OR (biz_type = 4 AND biz_id BETWEEN 5101 AND 5199) OR (biz_type = 5 AND biz_id BETWEEN 6101 AND 6199));

SELECT '=== 孤儿外键自查(应为空) ===' AS info;
SELECT 'business→customer' AS rel, COUNT(*) AS c FROM crm_business b LEFT JOIN crm_customer c ON c.id = b.customer_id AND c.tenant_id = b.tenant_id WHERE b.tenant_id = 2012 AND b.id BETWEEN 5101 AND 5199 AND c.id IS NULL
UNION ALL SELECT 'contact→customer', COUNT(*) FROM crm_contact t LEFT JOIN crm_customer c ON c.id = t.customer_id AND c.tenant_id = t.tenant_id WHERE t.tenant_id = 2012 AND t.id BETWEEN 4101 AND 4199 AND c.id IS NULL
UNION ALL SELECT 'businessProduct→product', COUNT(*) FROM crm_business_product t LEFT JOIN crm_product p ON p.id = t.product_id AND p.tenant_id = t.tenant_id WHERE t.tenant_id = 2012 AND t.business_id BETWEEN 5101 AND 5199 AND p.id IS NULL
UNION ALL SELECT 'contract→business', COUNT(*) FROM crm_contract t LEFT JOIN crm_business b ON b.id = t.business_id AND b.tenant_id = t.tenant_id WHERE t.tenant_id = 2012 AND t.id BETWEEN 6101 AND 6199 AND t.business_id IS NOT NULL AND b.id IS NULL;
